-- ---------------------------------------------------------------------------
-- B) ScriptName wiring
-- ---------------------------------------------------------------------------
-- Faerie Dragon and Raging Firestorm use the Hyjal +3,600,000 clone convention.
-- Twilight Inciter is bound at the RAW id 39926 because that is what the summon
-- spell (74514) and the quest objective both reference, and because this DB's
-- raw 39926 is a fully-configured template (level 80, hostile faction 2232, one
-- model) while no 3639926 clone exists.
--
-- Grove Warden (3639941) gets a small companion AI for its walk-out-and-return;
-- it has no spawns of its own and is only ever summoned by a Raging Firestorm.
-- ---------------------------------------------------------------------------
UPDATE `creature_template` SET `ScriptName` = 'npc_mh_faerie_dragon'    WHERE `entry` = 3639921;
UPDATE `creature_template` SET `ScriptName` = 'npc_mh_twilight_inciter' WHERE `entry` = 39926;
UPDATE `creature_template` SET `ScriptName` = 'npc_mh_raging_firestorm' WHERE `entry` = 3639939;
UPDATE `creature_template` SET `ScriptName` = 'npc_mh_grove_warden'     WHERE `entry` = 3639941;

-- ---------------------------------------------------------------------------
-- C) Barrow Dens areatrigger -- completes quest 25325 "Through the Dream"
-- ---------------------------------------------------------------------------
-- Areatrigger id 5876, taken from cata_world.areatrigger_scripts (same id space
-- as ours -- AreaTrigger.dbc ids are Blizzard data and are not offset).
-- ---------------------------------------------------------------------------
DELETE FROM `areatrigger_scripts` WHERE `entry` = 5876;
INSERT INTO `areatrigger_scripts` (`entry`,`ScriptName`) VALUES
(5876,'at_mh_hyjal_barrow_dens');

-- ---------------------------------------------------------------------------
-- D) Granting "Feed Berries" (74513) to the player
-- ---------------------------------------------------------------------------
-- READ THIS BEFORE CHANGING IT -- this is the one piece that is a judgement
-- call rather than a transcription.
--
-- Nothing records how the player obtains 74513: it is not on any item in this
-- DB, and cata_world has no spell_area, npc_spellclick or quest reward granting
-- it either. Retail delivered it as a quest-scoped ability, so it is reproduced
-- with the standard AzerothCore mechanism for exactly that -- a `spell_area`
-- row that auto-casts the ability while the player is in Hyjal (area 4923) with
-- quest 25370 active, and removes it when the quest leaves that state.
--
-- If you would rather deliver it as a provided quest item, delete this row and
-- give quest 25370 a StartItem whose spellid_1 = 74513 / spelltrigger_1 = 0
-- instead; the C++ side does not care which way the player comes to cast it.
--
-- Field semantics, because they are genuinely misleading (SpellMgr.cpp
-- SpellArea::IsFitToRequirements): `quest_end` is NOT "remove the aura when the
-- quest reaches this state" -- it is a SECOND positive requirement, ANDed with
-- quest_start. Both are tested as `(1 << player->GetQuestStatus(q)) & mask`.
-- So quest_end is left at 0 here (the check is skipped entirely) and the window
-- is expressed once, in quest_start_status.
--   quest_start_status = 8 = 1 << 3 = QUEST_STATUS_INCOMPLETE only, i.e. the
--   ability exists exactly while the quest is active and vanishes the moment
--   the 4th kill completes it.
-- ---------------------------------------------------------------------------
DELETE FROM `spell_area` WHERE `spell` = 74513 AND `area` = 4923;
INSERT INTO `spell_area` (`spell`,`area`,`quest_start`,`quest_start_status`,`quest_end`,`quest_end_status`,`aura_spell`,`racemask`,`gender`,`autocast`) VALUES
(74513,4923,25370,8,0,11,0,0,2,1);

-- ---------------------------------------------------------------------------
-- E) creature_text for the two new speakers
-- ---------------------------------------------------------------------------
-- The AI Talk() groups the port uses. Text is written to match the retail
-- flavour of the encounter; these lines are NOT recovered Blizzard strings, so
-- adjust freely. Faerie Dragon groups 0/1, Twilight Inciter group 0.
-- ---------------------------------------------------------------------------
DELETE FROM `creature_text` WHERE `CreatureID` IN (3639921,39926);
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`comment`) VALUES
(3639921,0,0,'The faerie dragon nibbles the berries and darts away, sniffing at the air.',16,0,100,0,0,0,0,'Faerie Dragon - fed berries'),
(3639921,1,0,'The faerie dragon shrieks and points -- something is hiding there!',16,0,100,0,0,0,0,'Faerie Dragon - infiltrator found'),
(39926,0,0,'You should not have come looking, $n.',12,0,100,0,0,0,0,'Twilight Inciter - spotted');

-- ---------------------------------------------------------------------------
-- Verification after applying + restart:
--   -- all 10 spells present:
--   SELECT COUNT(*) FROM spell_dbc WHERE ID IN (74513,74514,74515,74565,75192,75206,76205,76212,80549,80576);
--   -- four scripts bound:
--   SELECT entry, name, ScriptName FROM creature_template
--    WHERE entry IN (3639921,39926,3639939,3639941);
--   -- and in game: accept quest 25370, use Feed Berries on a Faerie Dragon,
--   -- follow it, kill the Twilight Inciter it reveals. x4 completes the quest.
-- ---------------------------------------------------------------------------
